 d={'id':key,'label':a['label'],'document_role':'main','page':a['source_pdf_page'],'printed_page':e['printed_page'],'source_locators':[e['locator']],'caption_paraphrase':caption,'sample_scope':scope,'sample_links':[P+r for r in records],'sample_linkage':'Explicit source cohort association only; shared host chemistry does not identify a physical specimen across substrates or techniques.','evidence_class':classification,'public_asset':a['public_asset'],'public_asset_sha256':a['sha256'],'asset_provenance':{'source_file':a['source_filename'],'source_sha256':a['source_sha256'],'source_pdf_page':a['source_pdf_page'],'crop_bbox_pdf_points_top_left':a['crop_bbox_pdf_points_top_left'],'crop_normalized':a['crop_normalized'],'render_dpi':a['render_dpi'],'pixel_dimensions':a['pixel_dimensions'],'renderer':'PDFium 300 dpi original-source crop','transformation':a['transformation']},'quantitative_context':list(notes),'panels':list(panels),'notes':list(notes),'axes':list(axes),'text_reviewed':True,'visual_reviewed':True,'reviewed':False,'reader_render_verified':False,'training_eligible':False,'source_asset_type':a['source_asset_type']}
